// ─── File: CommandDemo.java ───
package com.bank.command;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class CommandDemo {
    private static final Logger log = Logger.getLogger(CommandDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountService accounts = new AccountService();        // receiver
        accounts.open("SAV2001", new BigDecimal("1000000"));   // Rajesh
        accounts.open("CUR3001", new BigDecimal("250000"));    // Priya

        CommandInvoker invoker = new CommandInvoker();

        // QUEUE: build a batch of commands (a transfer macro + a fee debit)
        BigDecimal rentAmount = new BigDecimal("50000");
        invoker.enqueue(new TransferMacroCommand(accounts, "SAV2001", "CUR3001", rentAmount));
        invoker.enqueue(new DebitCommand(accounts, "SAV2001", new BigDecimal("50"))); // fee

        // LOG + EXECUTE the whole queue in order
        invoker.runAll();
        log.info(() -> "After batch: Rajesh=" + accounts.balance("SAV2001")
            + " Priya=" + accounts.balance("CUR3001"));

        // UNDO the entire batch in reverse order
        invoker.undoAll();
        log.info(() -> "After undo : Rajesh=" + accounts.balance("SAV2001")
            + " Priya=" + accounts.balance("CUR3001"));
    }
}

// ─── COMMAND INTERFACE ───
interface Command { void execute(); void undo(); String describe(); }

// ─── RECEIVER: does the real work, knows nothing about commands ───
class AccountService {
    private final Map<String, BigDecimal> balances = new HashMap<>();
    void open(String id, BigDecimal bal){ balances.put(id, bal); }
    void debit(String id, BigDecimal amt){
        BigDecimal b = balances.get(id);
        if (b.compareTo(amt) < 0) throw new IllegalStateException("Insufficient funds " + id);
        balances.put(id, b.subtract(amt));
    }
    void credit(String id, BigDecimal amt){ balances.put(id, balances.get(id).add(amt)); }
    BigDecimal balance(String id){ return balances.get(id); }
}

// ─── CONCRETE COMMANDS (execute + exact inverse undo) ───
class DebitCommand implements Command {
    private final AccountService svc; private final String id; private final BigDecimal amt;
    DebitCommand(AccountService s, String id, BigDecimal a){ svc=s; this.id=id; amt=a; }
    public void execute(){ svc.debit(id, amt); } public void undo(){ svc.credit(id, amt); }
    public String describe(){ return "DEBIT " + id + " Rs." + amt; }
}
class CreditCommand implements Command {
    private final AccountService svc; private final String id; private final BigDecimal amt;
    CreditCommand(AccountService s, String id, BigDecimal a){ svc=s; this.id=id; amt=a; }
    public void execute(){ svc.credit(id, amt); } public void undo(){ svc.debit(id, amt); }
    public String describe(){ return "CREDIT " + id + " Rs." + amt; }
}

// ─── MACRO COMMAND: compose commands; undo reverses them in reverse order ───
class TransferMacroCommand implements Command {
    private final List<Command> steps = new ArrayList<>();
    private final String from, to; private final BigDecimal amt;
    TransferMacroCommand(AccountService svc, String from, String to, BigDecimal amt){
        this.from=from; this.to=to; this.amt=amt;
        steps.add(new DebitCommand(svc, from, amt));
        steps.add(new CreditCommand(svc, to, amt));
    }
    public void execute(){ steps.forEach(Command::execute); }
    public void undo(){ for (int i = steps.size()-1; i >= 0; i--) steps.get(i).undo(); }
    public String describe(){ return "TRANSFER " + from + "->" + to + " Rs." + amt; }
}

// ─── INVOKER: queues, logs, executes, and undoes — never knows the receiver ───
class CommandInvoker {
    private static final Logger log = Logger.getLogger(CommandInvoker.class.getName());
    private final Queue<Command> queue = new ArrayDeque<>();
    private final Deque<Command> executed = new ArrayDeque<>();
    void enqueue(Command c){ queue.add(c); }
    void runAll(){
        while (!queue.isEmpty()) {
            Command c = queue.poll();
            log.info(() -> "LOG execute: " + c.describe());   // audit log before executing
            c.execute();
            executed.push(c);                                  // history for undo
        }
    }
    void undoAll(){
        while (!executed.isEmpty()) {
            Command c = executed.pop();
            log.info(() -> "LOG undo   : " + c.describe());
            c.undo();
        }
    }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
